-- Tone of voice, from the brand team's document.
-- Replaces the page only if it is empty or its JSON is invalid, so it
-- repairs the corrupted first attempt without touching real edits.
UPDATE pages SET blocks = '[{"type":"rich_text","data":{"heading":"","body":"Leading from strength is always more powerful than pointing out others'' weaknesses.\\n\\nWe''re not just delivering meals. We''re supporting healthier, happier, longer lives for dogs, and peace of mind for the people who love them. Our words carry our values.\\n\\nEvery sentence is a chance to build trust, brighten someone''s day, or explain something important in a way that feels effortless. And just like the dogs we feed, we want our voice to be full of life."},"options":{"size":"lead","align":"left","columns":"one"},"settings":{"width":"text","background":"none","spacing":"normal","divider":"no","anchor":""}},{"type":"rich_text","data":{"heading":"Our principles in brief","body":"If you work at Years, these are for you. Everyone who works here is a custodian of our brand and voice."},"options":{"size":"inherit","align":"left","columns":"one"},"settings":{"width":"text","background":"none","spacing":"normal","divider":"yes","anchor":"principles"}},{"type":"rich_text","data":{"heading":"Friendly, not fluffy","body":"We speak like people, not corporations. We''re warm, a little fun, and refreshingly clear: the kind of voice you''d expect from a good mate who loves dogs.\\n\\nThis applies all the time, to all the writing we do."},"options":{"size":"inherit","align":"left","columns":"one"},"settings":{"width":"text","background":"none","spacing":"normal","divider":"no","anchor":""}},{"type":"rich_text","data":{"heading":"Expert but accessible","body":"We balance scientific authority with human language. We reference studies and credentials, but always explain what it means in plain English.\\n\\nThis mainly applies to product information, educational content, and anything explaining nutrition or health."},"options":{"size":"inherit","align":"left","columns":"one"},"settings":{"width":"text","background":"none","spacing":"normal","divider":"no","anchor":""}},{"type":"rich_text","data":{"heading":"Show, don''t just tell","body":"We''re radically transparent. We share exact percentages, detailed breakdowns, and actual photos of what''s in the bowl, because trust is built on proof, not promises.\\n\\nThis belongs across product pages, ingredient lists, and anywhere we''re explaining what makes Years different."},"options":{"size":"inherit","align":"left","columns":"one"},"settings":{"width":"text","background":"none","spacing":"normal","divider":"no","anchor":""}},{"type":"rich_text","data":{"heading":"Friendly, not fluffy, in full","body":"The thread that runs through all of our writing. We speak like people, with heart and a human touch. We''re playful when appropriate, but never patronising.\\n\\nNo matter what kind of writing you do at Years, you should always be following this principle."},"options":{"size":"inherit","align":"left","columns":"one"},"settings":{"width":"text","background":"none","spacing":"normal","divider":"yes","anchor":"friendly"}},{"type":"rich_text","data":{"heading":"Human first, dog always","body":"We speak to our humans with empathy, clarity and care, but always with joy and enthusiasm. Every message should reflect our shared love of dogs, and a little shared chaos too."},"options":{"size":"inherit","align":"left","columns":"one"},"settings":{"width":"text","background":"none","spacing":"normal","divider":"no","anchor":""}},{"type":"do_dont","data":{"heading":"","pairs":[{"stance":"do","rule":"We''ve all been there. Your pup turns their nose up at dinner like you just served a bowl of air. Here''s what you can do about it.","why":""},{"stance":"dont","rule":"Please consult your subscription dashboard to update meal preferences.","why":""}]},"options":{"layout":"rows"},"settings":{"width":"text","background":"none","spacing":"tight","divider":"no","anchor":""}},{"type":"rich_text","data":{"heading":"Clear is kind","body":"Our customers aren''t just pet parents, they''re busy people. We keep things simple and skip the jargon. No one needs to decode ingredients, terms or instructions. If it''s not crystal clear, we rewrite it."},"options":{"size":"inherit","align":"left","columns":"one"},"settings":{"width":"text","background":"none","spacing":"normal","divider":"no","anchor":""}},{"type":"do_dont","data":{"heading":"","pairs":[{"stance":"do","rule":"This means your subscription is paused and you won''t be charged again unless you restart.","why":""},{"stance":"dont","rule":"In accordance with the recurring billing agreement, your service has been deactivated until reactivation is confirmed.","why":""}]},"options":{"layout":"rows"},"settings":{"width":"text","background":"none","spacing":"tight","divider":"no","anchor":""}},{"type":"rich_text","data":{"heading":"Puns, when they work","body":"We''ll say paw-sonalised or pawesome when it feels right, not forcing thank chew into every sentence. A wink, not a whole pantomime.\\n\\nWe steer clear of baby talk and anything that might feel overly cutesy or insincere. It''s a delicate balance: we''re playful, not patronising."},"options":{"size":"inherit","align":"left","columns":"one"},"settings":{"width":"text","background":"none","spacing":"normal","divider":"no","anchor":""}},{"type":"rich_text","data":{"heading":"Community over company","body":"We''re not a faceless dog food brand. We''re part of a growing pack, a family of dogs and the people who love them. We talk like teammates. We celebrate our customers. We learn from them. And we listen."},"options":{"size":"inherit","align":"left","columns":"one"},"settings":{"width":"text","background":"none","spacing":"normal","divider":"no","anchor":""}},{"type":"do_dont","data":{"heading":"","pairs":[{"stance":"do","rule":"Got a picky pup or a big question? Our team are just a message away, and happy to help.","why":""},{"stance":"dont","rule":"If you require further assistance, please reach out to our support department.","why":""}]},"options":{"layout":"rows"},"settings":{"width":"text","background":"none","spacing":"tight","divider":"no","anchor":""}},{"type":"rich_text","data":{"heading":"Short sentences are great","body":"Short sentences win. Keep sentences clear and punchy. If you find yourself stringing five commas together, it''s time to chop things up."},"options":{"size":"inherit","align":"left","columns":"one"},"settings":{"width":"text","background":"none","spacing":"normal","divider":"no","anchor":""}},{"type":"do_dont","data":{"heading":"","pairs":[{"stance":"do","rule":"Need help? Just reply to this email.","why":""},{"stance":"dont","rule":"If you require further assistance regarding your recent purchase, please don''t hesitate to get in touch with our support team at your earliest convenience.","why":""}]},"options":{"layout":"rows"},"settings":{"width":"text","background":"none","spacing":"tight","divider":"no","anchor":""}},{"type":"rich_text","data":{"heading":"Expert but accessible, in full","body":"We balance scientific credibility with human language. When you''ve got Board Certified Veterinary Nutritionists and peer-reviewed studies behind the product, you should talk about it, just in a way that doesn''t require a PhD to understand."},"options":{"size":"inherit","align":"left","columns":"one"},"settings":{"width":"text","background":"none","spacing":"normal","divider":"yes","anchor":"expert"}},{"type":"rich_text","data":{"heading":"Lead with our strengths","body":"We''re proud of what we''ve achieved and we say so clearly. When we''ve earned recognition, like our 96% rating or Board Certified formulation, we share it. We don''t need to compare ourselves to others; our results speak for themselves."},"options":{"size":"inherit","align":"left","columns":"one"},"settings":{"width":"text","background":"none","spacing":"normal","divider":"no","anchor":""}},{"type":"do_dont","data":{"heading":"","pairs":[{"stance":"do","rule":"Rated 96% by All About Dog Food, the highest fresh food rating achieved.","why":""},{"stance":"dont","rule":"Unlike other brands who hide their ingredients, we...","why":""}]},"options":{"layout":"rows"},"settings":{"width":"text","background":"none","spacing":"tight","divider":"no","anchor":""}},{"type":"rich_text","data":{"heading":"Authority does not require complexity","body":"We reference our Board Certified Veterinary Nutritionist and peer-reviewed studies, but always explain what it means in plain English. Science should enlighten, not confuse."},"options":{"size":"inherit","align":"left","columns":"one"},"settings":{"width":"text","background":"none","spacing":"normal","divider":"no","anchor":""}},{"type":"do_dont","data":{"heading":"","pairs":[{"stance":"do","rule":"Our Board Certified Veterinary Nutritionist formulated these meals based on the Gerard Lippert longevity study, research that shows dogs thrive on wholefood, minimally processed diets.","why":""},{"stance":"dont","rule":"Scientifically optimised nutritional matrices for canine wellness.","why":""}]},"options":{"layout":"rows"},"settings":{"width":"text","background":"none","spacing":"tight","divider":"no","anchor":""}},{"type":"rich_text","data":{"heading":"Simple language, comprehensive information","body":"Keep it simple does not mean give less information. It means explaining complex things clearly. We provide the detail people need to make informed decisions, exact percentages, nutritional breakdowns, ingredient sources, but in language everyone can understand."},"options":{"size":"inherit","align":"left","columns":"one"},"settings":{"width":"text","background":"none","spacing":"normal","divider":"no","anchor":""}},{"type":"do_dont","data":{"heading":"","pairs":[{"stance":"do","rule":"Chicken Leg (23%) [Chicken thigh 60%, Chicken drumstick 40%]","why":""},{"stance":"dont","rule":"Contains premium chicken","why":""}]},"options":{"layout":"rows"},"settings":{"width":"text","background":"none","spacing":"tight","divider":"no","anchor":""}},{"type":"rich_text","data":{"heading":"Educate, never preach","body":"We teach people about dog nutrition because we genuinely want them to understand. But we''re guides, not lecturers. We share knowledge in a way that empowers people to make better choices for their dogs."},"options":{"size":"inherit","align":"left","columns":"one"},"settings":{"width":"text","background":"none","spacing":"normal","divider":"no","anchor":""}},{"type":"rich_text","data":{"heading":"Show, don''t just tell, in full","body":"We''re radically transparent. In an industry where vague claims are the norm, we show our work. Every percentage, every ingredient, every nutritional breakdown: if we can measure it, we share it."},"options":{"size":"inherit","align":"left","columns":"one"},"settings":{"width":"text","background":"none","spacing":"normal","divider":"yes","anchor":"show"}},{"type":"rich_text","data":{"heading":"Transparent to the decimal","body":"We declare the percentage of every ingredient because we have nothing to hide. When we say 60% prime meat, we mean it, and we''ll show exactly what cuts and in what proportions."},"options":{"size":"inherit","align":"left","columns":"one"},"settings":{"width":"text","background":"none","spacing":"normal","divider":"no","anchor":""}},{"type":"do_dont","data":{"heading":"","pairs":[{"stance":"do","rule":"List every ingredient with exact percentages: Chicken Leg (23%) [Chicken thigh 60%, Chicken drumstick 40%], Chicken Gizzards (22%), Chicken Heart (15%)","why":""},{"stance":"dont","rule":"Use vague terms like chicken meal or poultry by-products","why":""}]},"options":{"layout":"rows"},"settings":{"width":"text","background":"none","spacing":"tight","divider":"no","anchor":""}},{"type":"rich_text","data":{"heading":"Named specifics over vague claims","body":"We name the cut of meat (chicken thigh, turkey drumstick, forequarter beef steak), the variety of vegetable (red pepper, sweet potato, spinach leaf), even the exact supplements (marine collagen, rosehip powder, green-lipped mussel).\\n\\nGeneric terms hide compromise. Specific names build confidence."},"options":{"size":"inherit","align":"left","columns":"one"},"settings":{"width":"text","background":"none","spacing":"normal","divider":"no","anchor":""}},{"type":"rich_text","data":{"heading":"Visual proof matters","body":"We show photos of the actual food, not stock images or illustrations. People should see the recognisable pieces of meat, the vibrant vegetables, the whole ingredients. If it looks good enough for you to eat, that''s the point."},"options":{"size":"inherit","align":"left","columns":"one"},"settings":{"width":"text","background":"none","spacing":"normal","divider":"no","anchor":""}},{"type":"rich_text","data":{"heading":"Back achievements with evidence","body":"When we say we''re rated 96%, or formulated by a Board Certified Veterinary Nutritionist, or based on longevity research, we link to the source, show the certificate, reference the study. Bold claims need backup."},"options":{"size":"inherit","align":"left","columns":"one"},"settings":{"width":"text","background":"none","spacing":"normal","divider":"no","anchor":""}},{"type":"rich_text","data":{"heading":"More years together","body":"This is our north star. Every decision we make, every word we write, comes back to this: helping dogs and their people have more time together. It''s emotional, it''s powerful, and it''s why we exist."},"options":{"size":"large","align":"left","columns":"one"},"settings":{"width":"text","background":"purple","spacing":"normal","divider":"no","anchor":""}},{"type":"rich_text","data":{"heading":"Passionate, not preachy","body":"We care deeply about dog health and longevity, and that intensity is part of who we are. But we channel it into education and empowerment, not judgment. We''re excited to share what we know, not to make people feel bad about past choices."},"options":{"size":"inherit","align":"left","columns":"one"},"settings":{"width":"text","background":"none","spacing":"normal","divider":"no","anchor":""}},{"type":"rich_text","data":{"heading":"Celebrate the bond","body":"We acknowledge the special relationship between dogs and their people. It''s not just pets and owners, it''s family. Our language reflects the love, the chaos, the joy, and the profound connection that defines life with dogs."},"options":{"size":"inherit","align":"left","columns":"one"},"settings":{"width":"text","background":"none","spacing":"normal","divider":"no","anchor":""}},{"type":"rich_text","data":{"heading":"Voice characteristics","body":""},"options":{"size":"inherit","align":"left","columns":"one"},"settings":{"width":"text","background":"none","spacing":"tight","divider":"yes","anchor":"characteristics"}},{"type":"do_dont","data":{"heading":"","pairs":[{"stance":"do","rule":"Caring, not clinical","why":"We speak with empathy, not cold efficiency. Whether it''s about nutrition or deliveries, people should feel supported and understood."},{"stance":"do","rule":"Playful, not silly","why":"Humour is welcome, but we don''t lose sight of trust or clarity. We aim to delight, not distract."},{"stance":"do","rule":"Confident, not arrogant","why":"We''re proud of what we''ve built and we say so. But confidence should never cross into superiority. We''re on their side, always."},{"stance":"do","rule":"Specific, not vague","why":"In an industry built on ambiguity, we choose precision. Exact percentages, named ingredients, detailed nutritional data."}]},"options":{"layout":"columns"},"settings":{"width":"text","background":"none","spacing":"normal","divider":"no","anchor":""}},{"type":"rich_text","data":{"heading":"Style guidance","body":""},"options":{"size":"inherit","align":"left","columns":"one"},"settings":{"width":"text","background":"none","spacing":"tight","divider":"yes","anchor":"style"}},{"type":"rich_text","data":{"heading":"Oxford comma","body":"We use the Oxford comma. It keeps items in a list clear and makes them feel like separate things.\\n\\nWithout it, \\"nutritionists, behaviourists and Board Certified Veterinary Nutritionists\\" can read as though the behaviourists are the Board Certified Veterinary Nutritionists. With it, each group stands on its own."},"options":{"size":"inherit","align":"left","columns":"one"},"settings":{"width":"text","background":"none","spacing":"normal","divider":"no","anchor":""}},{"type":"do_dont","data":{"heading":"","pairs":[{"stance":"do","rule":"We work with nutritionists, behaviourists, and Board Certified Veterinary Nutritionists.","why":""},{"stance":"dont","rule":"We work with nutritionists, behaviourists and Board Certified Veterinary Nutritionists.","why":""}]},"options":{"layout":"rows"},"settings":{"width":"text","background":"none","spacing":"tight","divider":"no","anchor":""}},{"type":"rich_text","data":{"heading":"Starting sentences","body":"Yes, you can start a sentence with but, and, so or because. We do it when we talk. It sounds natural. So it''s fine when we write, too."},"options":{"size":"inherit","align":"left","columns":"one"},"settings":{"width":"text","background":"none","spacing":"normal","divider":"no","anchor":""}},{"type":"comparison_table","data":{"heading":"Word swaps","left":"We say","right":"We don''t say","rows":[{"left":"Send, pack","right":"Dispatch, fulfil","note":""},{"left":"On the way, out for delivery","right":"In transit","note":""},{"left":"Eat, enjoy, dig in","right":"Consume","note":""},{"left":"Fix","right":"Resolve","note":""},{"left":"Ask","right":"Enquire","note":""},{"left":"Reply, answer","right":"Response","note":""},{"left":"Get, arrive","right":"Receive","note":""},{"left":"Need, want","right":"Require","note":""},{"left":"Give","right":"Provide","note":""},{"left":"Use","right":"Utilise","note":""},{"left":"Help","right":"Assist","note":""},{"left":"Buy, get","right":"Purchase, acquire","note":""}]},"options":{"density":"compact","strike":"plain"},"settings":{"width":"text","background":"none","spacing":"normal","divider":"no","anchor":""}},{"type":"rich_text","data":{"heading":"Read it aloud","body":"If it''s not something you''d say out loud to a friend, it probably doesn''t belong in our writing. Try reading what you''ve written out loud. If it sounds like it came from a customer service script or an instruction manual, it''s time to loosen it up."},"options":{"size":"inherit","align":"left","columns":"one"},"settings":{"width":"text","background":"none","spacing":"normal","divider":"no","anchor":""}},{"type":"rich_text","data":{"heading":"How we sound across channels","body":"We adapt to context while staying true to our core principles. The balance shifts across different touch points."},"options":{"size":"inherit","align":"left","columns":"one"},"settings":{"width":"text","background":"none","spacing":"normal","divider":"yes","anchor":"channels"}},{"type":"comparison_table","data":{"heading":"","left":"Channel","right":"The balance","rows":[{"left":"Website and product pages","right":"Friendly high, Expert maxed, Show maxed","note":"Where we educate and inform. Comprehensive nutritional information, evidence-backed explanations."},{"left":"Email","right":"Friendly maxed, Expert low, Show low","note":"Like a friend who happens to know a lot about dog nutrition. Clear, warm, action-oriented."},{"left":"Customer service","right":"Friendly maxed, Expert medium, Show none","note":"No jargon and no jokes. If someone is contacting us, they need help. That is the only job in that moment."},{"left":"Social media","right":"Friendly maxed, Expert low, Show medium","note":"Most playful and community-focused. Cheekier and more casual, never punching down."},{"left":"Educational content","right":"Friendly high, Expert maxed, Show high","note":"Where we teach. Grounded in science, explained clearly."},{"left":"Packaging and inserts","right":"Show high, Mission high","note":"The product is in their hands. Reinforce confidence in the choice they made."}]},"options":{"density":"compact","strike":"plain"},"settings":{"width":"text","background":"none","spacing":"normal","divider":"no","anchor":""}},{"type":"rich_text","data":{"heading":"The quick sniff test","body":"Before you hit send or publish, ask yourself:"},"options":{"size":"inherit","align":"left","columns":"one"},"settings":{"width":"text","background":"none","spacing":"tight","divider":"yes","anchor":"sniff-test"}},{"type":"do_dont","data":{"heading":"","pairs":[{"stance":"do","rule":"Is it honest and clear?","why":"No jargon, no hiding behind fancy words. Would your nan understand it?"},{"stance":"do","rule":"Is it helpful?","why":"Does this actually answer the question or solve the problem, or are we filling space?"},{"stance":"do","rule":"Does it sound human?","why":"Read it aloud. Would you say this to someone face to face?"},{"stance":"do","rule":"Are we leading from strength?","why":"Are we talking about what we do well, or what others do badly?"},{"stance":"do","rule":"Have we shown, not just told?","why":"For any claim about quality or nutrition, do we provide the proof?"},{"stance":"do","rule":"Does it reflect our mission?","why":"Does this get us closer to helping dogs live longer, healthier lives?"}]},"options":{"layout":"columns"},"settings":{"width":"text","background":"none","spacing":"normal","divider":"no","anchor":""}}]', status = 'published',
    summary = 'How Years sounds, the three principles, and the checks before anything ships.'
  WHERE slug = 'tone-of-voice'
    AND (blocks IS NULL OR blocks = '' OR blocks = '[]' OR LOCATE(CHAR(10), blocks) > 0);
